import json,html
d=json.load(open('data.json'));e=html.escape;C=d['checked']
import re,os
SITE='https://ukshortletrules.co.uk/';PAGES=[]
def mknav(p):return f'<nav><a href="{p}index.html">Home</a>'+''.join(f'<a href="{p}{n["id"]}.html">{n["name"]}</a>' for n in d['nations'])+f'<a href="{p}councils.html">Councils</a><a href="{p}changes.html">Changes</a><a href="{p}uk-visitor-levy-map.html">Levy map</a><a href="{p}scotland-short-term-let-licence-guide.html">Scot licence guide</a><a href="{p}scotland-business-rates-checker.html">Scot rates checker</a><a href="{p}wales-registration-checker.html">Wales checker</a><a href="{p}newsletter.html">Newsletter</a></nav>'
def page(f,t,b,desc=None,full_title=None,head=''):
    p='../'*f.count('/');nav=mknav(p);PAGES.append(f)
    if p:b=b.replace('src="signup.js"',f'src="{p}signup.js"')
    desc=desc or f'{t}: licensing, planning, tax and levy rules for UK short-term and holiday lets, with official sources.'
    os.makedirs(os.path.dirname(f) or '.',exist_ok=True)
    open(f,'w').write(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(full_title or t+' | UK Short-Let Rules Tracker')}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{SITE}{f}"><link rel="stylesheet" href="{p}style.css">{head}</head><body><header><a class="brand" href="{p}index.html">UK Short-Let Rules Tracker</a>{nav}</header><main><h1>{e(t)}</h1>{b}</main><footer>Last checked {C}. General information only, not legal or tax advice. Always check the linked official source.<br><span class="small">Want to reach UK hosts? <a href="{p}sponsor.html">Sponsor the tracker</a></span></footer></body></html>''')
FORM='''<form class="signup" data-endpoint="%s"><input type="email" name="email" placeholder="you@example.com" required aria-label="Email"><input type="text" name="website" class="hp" tabindex="-1" autocomplete="off"><button>Subscribe</button><p class="msg small"></p></form><script src="signup.js"></script>''' % e(d.get('newsletter_endpoint',''))
src=lambda s:' '.join(f'<a href="{e(u)}" rel="nofollow">source</a>' for u in s) or '<em>no source yet</em>'
cards=''.join(f'<a class="card" href="{n["id"]}.html"><h2>{n["name"]}</h2><p>{e(n["summary"])}</p></a>' for n in d['nations'])
latest=''.join(f'<li><b>{c["date"]}</b> [{c["nation"]}] {e(c["text"])}</li>' for c in d['changes'][:4])
page('index.html','Current short-let rules across the UK',f'<p class="lead">Licensing, planning, tax and safety rules for UK holiday-let and short-term-let hosts, with links to official sources.</p><div class="grid">{cards}</div><h2>Free tools</h2><ul><li><a href="wales-registration-checker.html">Wales: do I need to register with the WRA?</a> (4-question checker)</li><li><a href="scotland-business-rates-checker.html">Scotland: business rates or council tax?</a> (140/70 nights checker)</li><li><a href="scotland-short-term-let-licence-guide.html">Scotland: how to get a short-term let licence</a> (steps and checklist)</li><li><a href="london-90-night-counter.html">London: 90-night rule counter</a> (add bookings from every platform)</li><li><a href="uk-visitor-levy-map.html">UK visitor levy and tourist tax map</a></li><li><a href="holiday-let-tax-after-fhl-abolition.html">Holiday let tax after the FHL abolition</a> (UK-wide guide)</li><li><a href="holiday-let-fire-safety-england.html">England: holiday let fire safety rules and checklist</a></li><li><a href="holiday-let-fire-safety-wales.html">Wales: holiday let fire safety rules and checklist</a></li><li><a href="northern-ireland-tourism-certificate-guide.html">Northern Ireland: how to get a Tourism NI certificate</a> (fees, inspection, checklist)</li></ul><h2>Latest changes</h2><ul>{latest}</ul><p><a href="changes.html">Full changes log</a></p><div class="box"><h2>Weekly "what changed" email</h2><p>One short, sourced email a week. Unsubscribe any time.</p>'+FORM+'</div>')
slug=lambda c:c.get('slug') or re.sub(r'[^a-z0-9]+','-',c['name'].lower().replace('&','and')).strip('-')
def nfaq(n):
    nm=n['name'];Q=[]
    for r in n['rules']:
        QT={'Licensing':'Do I need a licence to run a short-term let in {nm}?','Planning / control areas':'Do I need planning permission for a short-term let in {nm}?','Visitor levy':'Is there a visitor levy (tourist tax) on short-term lets in {nm}?','Tax (FHL)':'How are holiday lets taxed in {nm} now the FHL regime has ended?','Tax (FHL abolished)':'How are holiday lets taxed in {nm} now the FHL regime has ended?','Non-domestic rates thresholds':'When does a short-term let in {nm} pay business rates instead of council tax?','Registration scheme':'Is there a short-term let registration scheme in {nm}?','Planning use class (C5)':'Is there a new planning use class (C5) for short-term lets in {nm}?','London 90-night rule':'What is the London 90-night rule?','Business rates vs council tax':'When does a holiday let in {nm} pay business rates instead of council tax?','Overnight Visitor Levy':'Is {nm} bringing in an Overnight Visitor Levy?','Safety':'What safety rules apply to holiday lets in {nm}?','Registration (WRA)':'Do I need to register my holiday let with the Welsh Revenue Authority?','182-day rule (rates)':'What is the 182-day rule for holiday lets in {nm}?','182-day rule consultation':'Is the 182-day rule in {nm} changing?','Planning':'Do I need planning permission for a short-term let in {nm}?','Certification':'Do I need a Tourism NI certificate to let my property in {nm}?','Rates':'Does a holiday let in {nm} pay business rates?'}
        t=r['topic'];q=QT.get(t,f'What are the rules on {t} for short-term lets in {{nm}}?').format(nm=nm)
        Q.append((q,f'{r["status"]}. {r["text"]}'))
    ld=json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in Q]}).replace('</','<\\/')
    h=f'<h2>{nm} short-let rules: quick answers</h2>'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in Q)+'<p class="small">Answers summarise the table above. Follow each row\'s official source before acting.</p>'
    return h,f'<script type="application/ld+json">{ld}</script>'

for n in d['nations']:
    rows=''.join(f'<tr><td>{e(r["topic"])}</td><td><span class="tag{" warn" if "UNVERIFIED" in r["status"] else ""}">{e(r["status"])}</span></td><td>{e(r["text"])}</td><td>{src(r["sources"])}</td></tr>' for r in n['rules'])
    NF=nfaq(n)
    page(n['id']+'.html',n['name'],f'<p class="lead">{e(n["summary"])}</p>'+('<p class="box"><b>New:</b> <a href="wales-registration-checker.html">Do I need to register with the WRA? Take the 4-question checker</a><br><a href="holiday-let-fire-safety-wales.html">Fire safety for holiday lets in Wales: what the guide needs, plus a checklist</a></p>' if n['id']=='wales' else '<p class="box"><b>New:</b> <a href="scotland-short-term-let-licence-guide.html">How to get a short-term let licence: steps and a tick-off checklist</a></p>' if n['id']=='scotland' else '<p class="box"><b>New:</b> <a href="holiday-let-fire-safety-england.html">Fire safety for holiday lets: what the law needs, plus a checklist</a><br><a href="london-90-night-counter.html">Letting in London? Count your nights against the 90-night rule</a></p>' if n['id']=='england' else '<p class="box"><b>New:</b> <a href="northern-ireland-tourism-certificate-guide.html">How to get a Tourism NI certificate: fees, the inspection and a tick-off checklist</a></p>' if n['id']=='northern-ireland' else '')+f'<div class="tw"><table><tr><th>Topic</th><th>Status</th><th>Rule</th><th>Official source</th></tr>{rows}</table></div><p>Income tax on holiday lets: <a href="holiday-let-tax-after-fhl-abolition.html">how holiday lets are taxed since the FHL regime ended</a>.</p>'+(lambda L:f'<h2>Council pages</h2><p>Local rules, fees and key dates, with official sources:</p><ul>{L}</ul><p><a href="councils.html">All councils</a></p>' if L else '')(''.join(f'<li><a href="councils/{slug(c)}.html">{e(c["name"])}</a></li>' for c in d['councils'] if c['nation']==n['name'] and c['verified']))+NF[0],head=NF[1])
rows=''.join(f'<tr><td>{f'<a href="councils/{slug(c)}.html">{e(c["name"])}</a>' if c["verified"] else e(c["name"])}</td><td>{c["nation"]}</td><td>{e(c["rule"])}</td><td>{"✔" if c["verified"] else "<span class=\"tag warn\">unverified</span>"}</td><td>{src([c["source"]] if c["source"] else [])}</td></tr>' for c in d['councils'])
page('councils.html','Councils with notable local rules',f'<p>Click a council for its own page with official sources and key dates.</p><div class="tw"><table><tr><th>Council</th><th>Nation</th><th>Rule</th><th>Verified</th><th>Source</th></tr>{rows}</table></div>')
rows=''.join(f'<tr><td>{c["date"]}</td><td>{c["nation"]}</td><td>{e(c["text"])}</td><td>{src([c["source"]])}</td></tr>' for c in d['changes'])
page('changes.html','Changes log',f'<div class="tw"><table><tr><th>Date</th><th>Nation</th><th>Change</th><th>Source</th></tr>{rows}</table></div>')
page('newsletter.html','Weekly "what changed" newsletter','<p>One short email every week: what changed, what\'s coming, and deadlines.</p>'+FORM+'<p class="small">We store only your email address (with our email provider, Resend) to send this newsletter. Unsubscribe link in every email. No spam, no sharing.</p>')
page('sponsor.html','Sponsor the tracker','<p>The UK Short-Let Rules Tracker is a free, independent guide to the rules for UK holiday-let and short-term-let hosts.</p><p>If you would like to sponsor the tracker, or talk about another way of working together, please get in touch: <a href="mailto:hello@ukshortletrules.co.uk">hello@ukshortletrules.co.uk</a>.</p><p>Any sponsorship would be clearly labelled, and sponsors never affect the content.</p>')

